<script lang="ts">
 import {onMount,onDestroy,createEventDispatcher} from 'svelte';
 import {CollaborationClient,incompleteReviewFingerprint,teamRunBlocksStart,type TeamRun} from './collaboration-client';
 import LocalProviderConnection from '../company/LocalProviderConnection.svelte';
 export let companyId:string;export let actorId:string;export let accessSignal:AbortSignal;export let conversationId:string;
 export let bots:{id:string;name:string}[]=[];
 const dispatch=createEventDispatcher();
 let client:CollaborationClient,room:any=null,messages:any[]=[],run:TeamRun|null=null,bossId='',teammateIds:string[]=[],sourceMessageId='',loading=true,busy=false,error='',showProvider=false,stale=false,reviewedFingerprint='';
 let timer:ReturnType<typeof setTimeout>|undefined,pending:{fingerprint:string;key:string}|null=null;
 const terminal=(state:string)=>['COMPLETED','CANCELLED','DENIED','FAILED','BUDGET_EXHAUSTED','UNCERTAIN'].includes(state);
 const storageKey=()=>['starli-team-run',actorId,companyId,conversationId].join(':');
 $: reviewFingerprint=incompleteReviewFingerprint(run);
 $: blockedRun=teamRunBlocksStart(run,reviewedFingerprint);
 $: eligible=bots.filter(bot=>room?.agentIds?.includes(bot.id));
 $: sources=messages.filter(message=>message.speaker?.kind==='human'&&message.speaker?.id===actorId&&!message.deleted&&typeof message.content==='string');
 $: teammateIds=teammateIds.filter(id=>id!==bossId&&eligible.some(bot=>bot.id===id));
 function denied(cause:any){if([401,403,404].includes(cause?.status)){run=null;messages=[];room=null;dispatch('denied',{status:cause.status});}}
 function revoke(){clearTimeout(timer);client?.close();run=null;messages=[];room=null;pending=null;}
 async function context(){const result=await client.context();if(accessSignal.aborted)return;room=result.room;messages=result.messages;if(!result.messages.some((m:any)=>m.id===sourceMessageId&&m.speaker?.kind==='human'&&m.speaker?.id===actorId&&!m.deleted))sourceMessageId=result.messages.filter((m:any)=>m.speaker?.kind==='human'&&m.speaker?.id===actorId&&!m.deleted).at(-1)?.id||'';}
 function remember(value:TeamRun){if(run?.runId===value.runId&&(value.modelCalls<run.modelCalls||run.stopRequested&&!value.stopRequested||terminal(run.state)&&!terminal(value.state)))return;run={...value,messages:value.messages??(run?.runId===value.runId?run.messages:undefined)};stale=false;reviewedFingerprint='';try{sessionStorage.setItem(storageKey(),value.runId);const expected=incompleteReviewFingerprint(run);if(expected&&sessionStorage.getItem(storageKey()+':incomplete-review:'+value.runId)===expected)reviewedFingerprint=expected;}catch{}}
 async function refresh(){if(accessSignal.aborted||busy)return;loading=true;error='';try{await context();if(run)remember(await client.read(run.runId));stale=false;}catch(cause){if(!accessSignal.aborted){stale=true;error=(cause as Error).message;denied(cause);}}finally{loading=false;schedule();}}
 function schedule(){clearTimeout(timer);if(run&&!terminal(run.state)&&!accessSignal.aborted)timer=setTimeout(()=>void poll(),2000);}
 async function poll(){if(!run||busy||accessSignal.aborted)return;const id=run.runId;try{const current=await client.read(id);if(accessSignal.aborted)return;remember(current);await context();}catch(cause){if(!accessSignal.aborted){stale=true;error=(cause as Error).message;denied(cause);return;}}schedule();}
 async function start(){if(loading||busy||!bossId||!sourceMessageId||!teammateIds.length||teammateIds.length>4||blockedRun)return;busy=true;error='';clearTimeout(timer);try{await context();if(!room.agentIds.includes(bossId)||teammateIds.some(id=>!room.agentIds.includes(id))||!messages.some(m=>m.id===sourceMessageId&&m.speaker?.kind==='human'&&m.speaker?.id===actorId))throw Error('The selected team or initiating message changed. Refresh before starting.');const fingerprint=JSON.stringify([bossId,teammateIds,sourceMessageId]);if(pending?.fingerprint!==fingerprint)pending={fingerprint,key:crypto.randomUUID()};try{sessionStorage.setItem(storageKey()+':pending',JSON.stringify(pending));}catch{}remember(await client.start({bossId,teammateIds,sourceMessageId,idempotencyKey:pending.key}));pending=null;try{sessionStorage.removeItem(storageKey()+':pending');}catch{}}catch(cause){if(!accessSignal.aborted){error=(cause as Error).message+' No automatic retry was made.';denied(cause);}}finally{busy=false;schedule();}}
 async function stop(){if(!run||busy||terminal(run.state))return;busy=true;error='';clearTimeout(timer);try{remember(await client.stop(run.runId));}catch(cause){if(!accessSignal.aborted){stale=true;error='Stop could not be confirmed. Refresh this run before starting another.';denied(cause);}}finally{busy=false;schedule();}}
 function acknowledgeIncomplete(){if(stale||busy||!run)return;const expected=incompleteReviewFingerprint(run);if(!expected)return;try{sessionStorage.setItem(storageKey()+':incomplete-review:'+run.runId,expected);}catch{}reviewedFingerprint=expected;}
 function toggle(id:string,checked:boolean){teammateIds=checked?[...teammateIds,id]:teammateIds.filter(value=>value!==id);}
 onMount(()=>{client=new CollaborationClient(companyId,conversationId,()=>localStorage.token||'');accessSignal.addEventListener('abort',revoke,{once:true});void(async()=>{try{const stored=JSON.parse(sessionStorage.getItem(storageKey()+':pending')||'null');if(stored&&typeof stored.fingerprint==='string'&&stored.fingerprint.length<2048&&typeof stored.key==='string'&&/^[a-zA-Z0-9_-]{1,128}$/.test(stored.key))pending=stored;const id=sessionStorage.getItem(storageKey());if(id&&/^[a-zA-Z0-9_-]{1,128}$/.test(id))remember(await client.read(id));}catch{}if(!accessSignal.aborted)await refresh();})();});
 onDestroy(()=>{accessSignal.removeEventListener('abort',revoke);revoke();});
</script>

<section class="team" aria-label="Bounded team conversation">
 <header><div><h2>Team conversation</h2><p>Choose an admitted Boss and teammates. Their actual replies and final synthesis are saved in this conversation.</p></div><button type="button" disabled={busy||loading} on:click={refresh}>Refresh</button></header>
 {#if error}<p class="error" role="alert">{error}</p>{/if}
 <button class="setup" type="button" on:click={()=>showProvider=!showProvider}>{showProvider?'Hide model connection':'Connect team models'}</button>
 {#if showProvider}<LocalProviderConnection {companyId} {actorId} {accessSignal} bots={eligible}/>{/if}
 {#if loading&&!room}<p>Checking conversation membership…</p>{:else if room}
  {#if eligible.length<2}<p class="hint">This conversation needs at least two admitted bots. Use its Members controls to add the Boss and teammates before starting.</p>{/if}
  <label>Boss<select bind:value={bossId} disabled={busy||blockedRun}><option value="">Choose the coordinator</option>{#each eligible as bot}<option value={bot.id}>{bot.name}</option>{/each}</select></label>
  <fieldset disabled={busy||blockedRun}><legend>Teammates · choose 1–4</legend>{#each eligible.filter(bot=>bot.id!==bossId) as bot}<label class="check"><input type="checkbox" checked={teammateIds.includes(bot.id)} disabled={!teammateIds.includes(bot.id)&&teammateIds.length>=4} on:change={event=>toggle(bot.id,event.currentTarget.checked)}/>{bot.name}</label>{/each}</fieldset>{#if teammateIds.length}<p class="hint">Selected teammate order · first round follows this order</p><ol class="team-order" aria-label="Selected teammate order">{#each teammateIds as id}<li>{bots.find(bot=>bot.id===id)?.name||id}</li>{/each}</ol>{/if}
  <label>Your initiating message<select bind:value={sourceMessageId} disabled={busy||blockedRun}><option value="">Choose an existing message</option>{#each sources as message}<option value={message.id}>{message.content.slice(0,140)}</option>{/each}</select></label>
  {#if !sources.length}<p class="hint">Send your task in this conversation first. The team run uses that persisted message as its objective.</p>{/if}
  <button class="primary" type="button" on:click={start} disabled={loading||busy||stale||!bossId||!teammateIds.length||!sourceMessageId||blockedRun}>{busy?'Waiting for confirmation…':'Start bounded team run'}</button>
  <p class="hint">Starting sends actual model requests through each bot’s saved provider. The run is bounded by server budgets and has no tools or external-action authority.</p>
 {/if}
 {#if run}<section class="run" aria-label="Team run status"><h3>{run.state}{stale?' · status unavailable':''}</h3><p role="status">Round {run.round} · {run.modelCalls} model calls recorded</p>{#if run.confirmedStopped}<p>Stopped and confirmed.</p>{:else if run.stopRequested}<p>Stop requested; completion is not yet confirmed.</p>{/if}{#if run.needsReview}<p class="error">{reviewFingerprint?'This earlier discussion ended without replies from every selected teammate. Its saved messages remain below.':'This run needs review. Check persisted messages before starting other work.'}</p>{#if reviewFingerprint}<p class="hint">Missing replies: {run.participantCoverage?.missingIds.map(id=>bots.find(bot=>bot.id===id)?.name||id).join(', ')}</p>{#if reviewedFingerprint===reviewFingerprint}<p role="status" class="hint">Review recorded for this discussion. You may explicitly start a new run. The earlier result remains incomplete.</p>{:else}<button type="button" disabled={busy||stale} on:click={acknowledgeIncomplete}>I reviewed this incomplete discussion</button>{/if}{/if}{/if}{#if run.errorCode}<p class="hint">{run.errorCode}</p>{/if}{#if !terminal(run.state)}<button class="stop" type="button" disabled={busy} on:click={stop}>Request Stop</button>{/if}<p class="hint">Boss: {bots.find(b=>b.id===run?.bossId)?.name||run.bossId}</p><ol class="team-order" aria-label="Run teammate order">{#each run.teammateIds as id}<li>{bots.find(bot=>bot.id===id)?.name||id}</li>{/each}</ol>{#each run.messages?.filter(message=>message.state==='POSTED'&&message.messageId)||[] as message}<article><strong>{bots.find(b=>b.id===message.botId)?.name||message.botId}</strong><small>{message.kind}</small><p>{message.content}</p></article>{/each}</section>{/if}
</section>
<style>.team-order{padding-left:24px;list-style:decimal;line-height:1.8;font-size:12px}.team{padding:24px;color:#17243f;font-size:13px}header{display:flex;gap:16px;justify-content:space-between}h2{font-size:18px;margin:0}h3{font-size:14px}header p,.hint{color:#71809a;font-size:12px;line-height:1.6}button{border:1px solid #dfe6f2;border-radius:8px;background:#fff;color:#475569;padding:9px 12px;font:inherit;cursor:pointer;align-self:flex-start}button:disabled{opacity:.45;cursor:default}.primary{background:#2563eb;color:white;border-color:#2563eb}.stop{color:#be123c;border-color:#fecdd3}.setup{margin:12px 0}label{display:grid;gap:8px;margin:16px 0;font-size:12px;font-weight:600}select{padding:10px;border:1px solid #dfe6f2;border-radius:8px;background:#fafdff;width:100%;color:#17243f;font:inherit}fieldset{border:1px solid #e6ebf4;border-radius:10px;padding:12px}legend{font-size:12px}.check{display:flex;gap:8px;align-items:center;font-weight:400;margin:9px 0}.error{padding:10px;background:#fff0f2;border-radius:8px;color:#be123c;line-height:1.5}.run{margin-top:24px;padding-top:12px;border-top:1px solid #e6ebf4}.run article{border:1px solid #e6ebf4;border-radius:10px;padding:14px;margin-top:12px}.run small{display:block;color:#71809a;margin-top:4px}.run article p{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.7}button:focus-visible,select:focus-visible,input:focus-visible{outline:2px solid #9cb7ff;outline-offset:2px}</style>
